//! Shared vectors generated by src/graph/__tests__/engine-scanner-vectors.test.ts.

use mex_graph_ecmascript::scanner::scan_token_names;
use serde::Deserialize;

#[derive(Deserialize)]
struct Vectors {
    cases: Vec<Vector>,
}

#[derive(Deserialize)]
struct Vector {
    text: String,
    standard: Vec<String>,
    jsx: Vec<String>,
}

#[test]
fn scanner_tokens_equal_typescript() {
    let vectors: Vectors =
        serde_json::from_str(include_str!("scanner-vectors.json")).expect("valid scanner vectors");
    for vector in vectors.cases {
        for (jsx, expected) in [(false, &vector.standard), (true, &vector.jsx)] {
            assert_eq!(
                scan_token_names(&vector.text, jsx),
                *expected,
                "text {:?}, jsx {jsx}",
                vector.text,
            );
        }
    }
}
